∀ {ℋ₁ : Type u} {ℋ₂ : Type v} [inst : QuantumState.Qudit ℋ₁] [inst_1 : QuantumState.Qudit ℋ₂] {ι : Type u_1}
  {inst_2 : DecidableEq ι} [inst_3 : DecidableEq ι] [inst_4 : Fintype ι] (b b_1 : Module.Basis ι ℂ ℋ₂),
  b = b_1 → QuantumChannel.vecLinearEquiv b = QuantumChannel.vecLinearEquiv b_1

∀ (H : Type u) [inst : QuantumState.Qudit H] [inst_1 : Nontrivial H],
  QuantumChannelContinuity.DensityState.maximallyMixed H =
    { op := (↑(Module.finrank ℂ H))⁻¹ • 1, nonneg := ⋯, trace_one := ⋯ }

∀ {H : Type u} [inst : QuantumState.Qudit H] (op op_1 : QuantumState.L H) (e_op : op = op_1) (nonneg : 0 ≤ op)
  (trace_one : QuantumState.Tr op = 1),
  { op := op, nonneg := nonneg, trace_one := trace_one } = { op := op_1, nonneg := ⋯, trace_one := ⋯ }

∀ {H : Type u} {inst : QuantumState.Qudit H} {op : QuantumState.L H} {nonneg : 0 ≤ op}
  {trace_one : QuantumState.Tr op = 1} {op_1 : QuantumState.L H} {nonneg_1 : 0 ≤ op_1}
  {trace_one_1 : QuantumState.Tr op_1 = 1},
  { op := op, nonneg := nonneg, trace_one := trace_one } =
      { op := op_1, nonneg := nonneg_1, trace_one := trace_one_1 } →
    op = op_1

∀ {A B : Type u} [inst : QuantumState.Qudit A] [inst_1 : QuantumState.Qudit B] [inst_2 : Nontrivial A]
  [inst_3 : Nontrivial B] (ρ : QuantumChannelContinuity.DensityState A) (τ : QuantumChannelContinuity.DensityState B),
  ρ.tensor τ = { op := TensorProduct.map ρ.op τ.op, nonneg := ⋯, trace_one := ⋯ }

∀ {H : Type u} {inst : QuantumState.Qudit H} {op : QuantumState.L H} {nonneg : 0 ≤ op} {le_one : op ≤ 1}
  {op_1 : QuantumState.L H} {nonneg_1 : 0 ≤ op_1} {le_one_1 : op_1 ≤ 1},
  { op := op, nonneg := nonneg, le_one := le_one } = { op := op_1, nonneg := nonneg_1, le_one := le_one_1 } → op = op_1

∀ {H : Type} [inst : QuantumState.Qudit H] [Nontrivial H] {ι : Type} [inst_2 : Fintype ι] [inst_3 : DecidableEq ι]
  (M : QuantumChannelContinuity.POVM H ι) (k : ℕ) (X : CStarMatrix (Fin k) (Fin k) (QuantumState.L H)),
  0 ≤ X → 0 ≤ X.map ⇑{ toFun := ⇑M.linearMap, map_add' := ⋯, map_smul' := ⋯ }

∀ {H : Type} [inst : QuantumState.Qudit H] {ι : Type} [inst_1 : Fintype ι] (effect effect_1 : ι → QuantumState.L H)
  (e_effect : effect = effect_1) (nonneg : ∀ (i : ι), 0 ≤ effect i) (sum_one : ∑ i, effect i = 1),
  { effect := effect, nonneg := nonneg, sum_one := sum_one } = { effect := effect_1, nonneg := ⋯, sum_one := ⋯ }

∀ {H : Type} {inst : QuantumState.Qudit H} {ι : Type} {inst_1 : Fintype ι} {effect : ι → QuantumState.L H}
  {nonneg : ∀ (i : ι), 0 ≤ effect i} {sum_one : ∑ i, effect i = 1} {effect_1 : ι → QuantumState.L H}
  {nonneg_1 : ∀ (i : ι), 0 ≤ effect_1 i} {sum_one_1 : ∑ i, effect_1 i = 1},
  { effect := effect, nonneg := nonneg, sum_one := sum_one } =
      { effect := effect_1, nonneg := nonneg_1, sum_one := sum_one_1 } →
    effect = effect_1

∀ {H : Type u} {inst : QuantumState.Qudit H} {vector : H} {norm_one : ‖vector‖ = 1} {vector_1 : H}
  {norm_one_1 : ‖vector_1‖ = 1},
  { vector := vector, norm_one := norm_one } = { vector := vector_1, norm_one := norm_one_1 } → vector = vector_1

