declarations.type:
∀ {H K : Type} {inst : QuantumState.Qudit H} {inst_1 : QuantumState.Qudit K} {inst_2 : Nontrivial H}
  {inst_3 : Nontrivial K} {N M : QuantumChannel.CPTP H K}
  {relative_finite : QuantumChannelContinuity.regularizedRelative N M ≠ ⊤}
  {renyi_finite : ∀ (α : ℝ), 1 < α → QuantumChannelContinuity.regularizedRenyi α N M ≠ ⊤}
  {order_mono : MonotoneOn (fun α => (QuantumChannelContinuity.regularizedRenyi α N M).toReal) (Set.Ioi 1)}
  {relative_le_renyi :
    ∀ (α : ℝ),
      1 < α →
        (QuantumChannelContinuity.regularizedRelative N M).toReal ≤
          (QuantumChannelContinuity.regularizedRenyi α N M).toReal}
  {cap : ℝ}
  {raw_schatten :
    let a := fun α => (QuantumChannelContinuity.regularizedRenyi α N M).toReal;
    let dPlus := sInf (a '' Set.Ioi 1);
    ∀ (r : ℝ),
      0 ≤ r →
        r < dPlus →
          ∀ (t : ℝ),
            1 ≤ t →
              ∀ (n : ℕ),
                t < ↑n →
                  2 * t ≤ ↑n →
                    2 ^ (t * dPlus / 2) ≤
                      ChannelContinuity.rawSchattenRhs n t r dPlus cap √(QuantumChannelContinuity.blockTesting N M n r)
                        √(QuantumChannelContinuity.blockTesting N M n (dPlus + 1 / (t * t)))}
  {relative_finite_1 : QuantumChannelContinuity.regularizedRelative N M ≠ ⊤}
  {renyi_finite_1 : ∀ (α : ℝ), 1 < α → QuantumChannelContinuity.regularizedRenyi α N M ≠ ⊤}
  {order_mono_1 : MonotoneOn (fun α => (QuantumChannelContinuity.regularizedRenyi α N M).toReal) (Set.Ioi 1)}
  {relative_le_renyi_1 :
    ∀ (α : ℝ),
      1 < α →
        (QuantumChannelContinuity.regularizedRelative N M).toReal ≤
          (QuantumChannelContinuity.regularizedRenyi α N M).toReal}
  {cap_1 : ℝ}
  {raw_schatten_1 :
    let a := fun α => (QuantumChannelContinuity.regularizedRenyi α N M).toReal;
    let dPlus := sInf (a '' Set.Ioi 1);
    ∀ (r : ℝ),
      0 ≤ r →
        r < dPlus →
          ∀ (t : ℝ),
            1 ≤ t →
              ∀ (n : ℕ),
                t < ↑n →
                  2 * t ≤ ↑n →
                    2 ^ (t * dPlus / 2) ≤
                      ChannelContinuity.rawSchattenRhs n t r dPlus cap_1
                        √(QuantumChannelContinuity.blockTesting N M n r)
                        √(QuantumChannelContinuity.blockTesting N M n (dPlus + 1 / (t * t)))},
  { relative_finite := relative_finite, renyi_finite := renyi_finite, order_mono := order_mono,
        relative_le_renyi := relative_le_renyi, cap := cap, raw_schatten := raw_schatten } =
      { relative_finite := relative_finite_1, renyi_finite := renyi_finite_1, order_mono := order_mono_1,
        relative_le_renyi := relative_le_renyi_1, cap := cap_1, raw_schatten := raw_schatten_1 } →
    cap = cap_1

∀ {H : Type} [inst : QuantumState.Qudit H] (M : QuantumState.L H) (hM : 0 ≤ M) (hM1 : M ≤ 1),
  QuantumChannelContinuity.binaryPOVM M hM hM1 =
    { effect := fun i => if i = 0 then M else 1 - M, nonneg := ⋯, sum_one := ⋯ }

∀ {E : Type u_1} {F : Type u_2} [inst : QuantumState.Qudit E] [inst_1 : QuantumState.Qudit F] {ι : Type u_3}
  [inst_2 : Fintype ι] (C : ι → E →ₗ[ℂ] F),
  QuantumChannelContinuity.coefficientDensity (∑ i, C i) = ∑ i, ∑ j, C i ∘ₗ LinearMap.adjoint (C j)

declarations.docstring:
Transferring a two-piece decomposition to a prescribed environment
preserves its operator-norm error.  The alignment equality is explicit;
its existence is the separate dilation-uniqueness theorem.

