∀ {H : Type u_1} [inst : QuantumState.Qudit H] (m : ℝ) (x : ↥(QuantumChannelContinuity.Hermitian H)),
  { toFun := fun Y => (QuantumState.Tr (↑(m • x) * ↑Y)).re, map_add' := ⋯, map_smul' := ⋯ } =
    (RingHom.id ℝ) m • { toFun := fun Y => (QuantumState.Tr (↑x * ↑Y)).re, map_add' := ⋯, map_smul' := ⋯ }

∀ {A B : Type u_1} [inst : QuantumState.Qudit A] [inst_1 : QuantumState.Qudit B] (e : A ≃ₗᵢ[ℂ] B) (k : ℕ)
  (M : CStarMatrix (Fin k) (Fin k) (QuantumState.L A)),
  0 ≤ M → 0 ≤ M.map ⇑{ toFun := ⇑(QuantumChannelContinuity.isoConj e), map_add' := ⋯, map_smul' := ⋯ }

∀ {H : Type} [inst : QuantumState.Qudit H] {K : Type} [inst_1 : QuantumState.Qudit K] (M : QuantumState.L H) (e : K),
  QuantumChannelContinuity.measurementTerm M e =
    { toFun := fun γ => QuantumState.Tr (M * γ) • QuantumChannel.outer_product e e, map_add' := ⋯, map_smul' := ⋯ }

declarations.docstring:
Schatten `2p` triangle inequality for arbitrary finite families of rectangular
coefficient maps. This is the precise analytic triangle needed in the paper;
no invertibility or full-rank hypothesis is imposed.

